# Adaptive batch size scheduler for fixed-token training
# Strategy: Maximize small-batch efficiency early, detect corpus switch via step increase,
# then adaptively increase batch size based on observed step counts

def run(env):
    recent_steps = []
    step_baseline = None
    max_recent_steps = None

    for segment_idx in range(env.n_segments):
        # Adaptive batch selection based on segment and observed step trends
        if segment_idx < 5:
            # Very early segments: use aggressive small batch
            batch = 128
        elif segment_idx < 15:
            # Early phase: still use small batch for efficiency
            batch = 128
        elif segment_idx < 20:
            # Transition zone: moderate batch
            batch = 192
        else:
            # Late phase: monitor step counts to adapt
            # If we see high steps (corpus switch happened), use larger batch
            if len(recent_steps) > 0:
                current_steps = recent_steps[-1]
                if step_baseline and current_steps > step_baseline * 1.8:
                    # Significant increase in steps detected - likely post-switch
                    batch = 512
                elif max_recent_steps and current_steps > max_recent_steps * 0.9:
                    # Steps staying high - use moderately large batch
                    batch = 384
                else:
                    batch = 256
            else:
                batch = 256

        result = env.run_segment(batch)

        # Track step counts for adaptation
        steps = result['steps']
        recent_steps.append(steps)

        if step_baseline is None:
            step_baseline = steps

        if max_recent_steps is None:
            max_recent_steps = steps
        else:
            max_recent_steps = max(max_recent_steps, steps)

        # Keep only recent history
        if len(recent_steps) > 5:
            recent_steps.pop(0)

